/// <summary>
///     The <c>KCS_KBVActivitiesForBP</c> is the extension class for table <c>common</c>
/// </summary>
public class KCS_KBVActivitiesForBP extends common
{
}

Method.Source:
/// <summary>
///    AVA <c>createReference</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectID">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_smmActivityNumber">
///    <c>smmActivityNumber</c> as type
/// </param>
/// <param name="_dataAreaId">
///    <c>DataAreaid</c> as type
/// </param>
static void createReference(KCS_KBVBuildingProjectID    _kcs_KBVBuildingProjectID,
                            smmActivityNumber           _smmActivityNumber,
                            DataAreaid                  _dataAreaId = curExt())
{
    KCS_KBVActivitiesForBP  locRecord;

    if(_kcs_KBVBuildingProjectID && _smmActivityNumber && _dataAreaId)
    {
        changecompany(_dataAreaId)
        {
            locRecord.clear();
            locRecord.KCS_KBVBuildingProjectID  = _kcs_KBVBuildingProjectID;
            locRecord.smmActivityNumber         = _smmActivityNumber;
            //locRecord.DataAreaId                = _dataAreaId;
            locRecord.insert();
        }
    }
}

/// <summary>
///    AVA <c>exist</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectID">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_smmActivityNumber">
///    <c>smmActivityNumber</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
static boolean exist(   KCS_KBVBuildingProjectID    _kcs_KBVBuildingProjectID,
                        smmActivityNumber           _smmActivityNumber)
{
    // Prüft, ob es für ein Bauvorhaben für den aktuellen Mandanten eine Aktivität gibt
    boolean                 retVal;

    KCS_KBVActivitiesForBP  locKCS_KBVActivitiesForBP;

    if (!(_kcs_KBVBuildingProjectID && _smmActivityNumber))
    {
        return false;
    }

    select firstonly RecId
    from    locKCS_KBVActivitiesForBP
    where   locKCS_KBVActivitiesForBP.KCS_KBVBuildingProjectID  == _kcs_KBVBuildingProjectID
        &&  locKCS_KBVActivitiesForBP.smmActivityNumber         == _smmActivityNumber;

    if(locKCS_KBVActivitiesForBP.RecId)
    {
        retVal = true;
    }

    return retVal;
}

/// <summary>
///    AVA <c>existInCompanies</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectID">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_smmActivityNumber">
///    <c>smmActivityNumber</c> as type
/// </param>
/// <param name="_cDataAreaId">
///    <c>container</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
static boolean existInCompanies(KCS_KBVBuildingProjectID    _kcs_KBVBuildingProjectID,
                                smmActivityNumber           _smmActivityNumber,
                                container                   _cDataAreaId = [curExt()]   )
{
    // Prüft, ob es für ein Bauvorhaben in dem/den angegebenen Mandant/Mandanten eine Aktivität gibt
    boolean                 retVal;

    KCS_KBVActivitiesForBP  locKCS_KBVActivitiesForBP;
    container               cDataAreaId;

    if(_cDataAreaId != conNull())
    {
        cDataAreaId = _cDataAreaId;
    }
    else
    {
        cDataAreaId = AVAKBVBuildingProjectHelper::getAllBPCompanies();
    }

    if (!(_kcs_KBVBuildingProjectID && _smmActivityNumber))
    {
        return false;
    }

    select firstonly1 crosscompany : cDataAreaId RecId
    from    locKCS_KBVActivitiesForBP
    where   locKCS_KBVActivitiesForBP.KCS_KBVBuildingProjectID  == _kcs_KBVBuildingProjectID
        &&  locKCS_KBVActivitiesForBP.smmActivityNumber         == _smmActivityNumber;

    if(locKCS_KBVActivitiesForBP.RecId)
    {
        retVal = true;
    }

    return retVal;
}

/// <summary>
///    AVA <c>find</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectID">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_smmActivityNumber">
///    <c>smmActivityNumber</c> as type
/// </param>
/// <returns>
///    <c>KCS_KBVActivitiesForBP</c> as return value
/// </returns>
static KCS_KBVActivitiesForBP find( KCS_KBVBuildingProjectID    _kcs_KBVBuildingProjectID,
                                    smmActivityNumber           _smmActivityNumber)
{
    // Prüft, ob es für ein Bauvorhaben eine Aktivität gibt
    KCS_KBVActivitiesForBP  locKCS_KBVActivitiesForBP;

    if (!(_kcs_KBVBuildingProjectID && _smmActivityNumber))
    {
        return locKCS_KBVActivitiesForBP;
    }

    select firstonly1 locKCS_KBVActivitiesForBP
    where   locKCS_KBVActivitiesForBP.KCS_KBVBuildingProjectID  == _kcs_KBVBuildingProjectID
        &&  locKCS_KBVActivitiesForBP.smmActivityNumber         == _smmActivityNumber;

    return locKCS_KBVActivitiesForBP;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_kcs_KBVBuildingProjectID">KCS_KBVBuildingProjectID</param>
/// <returns>boolean</returns>
static boolean existRecForBP(   KCS_KBVBuildingProjectID    _kcs_KBVBuildingProjectID)
{
    boolean                 retVal;
    container               cDataAreaId;
    KCS_KBVActivitiesForBP  locKCS_KBVActivitiesForBP;

    if (!_kcs_KBVBuildingProjectID )
    {
        return false;
    }

    cDataAreaId = AVAKBVBuildingProjectHelper::getAllBPCompanies();

    select firstonly1 crosscompany : cDataAreaId RecId
    from    locKCS_KBVActivitiesForBP
        where   locKCS_KBVActivitiesForBP.KCS_KBVBuildingProjectID  == _kcs_KBVBuildingProjectID;

    if(locKCS_KBVActivitiesForBP.RecId)
    {
        retVal = true;
    }

    return retVal;
}
